class Queue {
  constructor() { this.items = []; }
  enqueue(v) { this.items.push(v); }
  dequeue() {
    // BUG: slice() reindexes the whole array -> O(n) per call
    const v = this.items[0];
    this.items = this.items.slice(1);
    return v;
  }
  isEmpty() { return this.items.length === 0; }
}

const q = new Queue();
[1, 2, 3, 4, 5].forEach(v => q.enqueue(v));
const out = [];
out.push(q.dequeue());
out.push(q.dequeue());
q.enqueue(6);
while (!q.isEmpty()) out.push(q.dequeue());
console.log(out.join(','));

